class Solution:
    def twoOutOfThree(self, nums1: list[int], nums2: list[int], nums3: list[int]) -> list[int]:
        s1, s2, s3 = set(nums1), set(nums2), set(nums3)
        return list((s1 & s2) | (s2 & s3) | (s1 & s3))

class Solution {
public:
    vector<int> twoOutOfThree(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3) {
        unordered_set<int> s1(nums1.begin(), nums1.end());
        unordered_set<int> s2(nums2.begin(), nums2.end());
        unordered_set<int> s3(nums3.begin(), nums3.end());
        unordered_set<int> res;
        for (int x : s1) if (s2.count(x) || s3.count(x)) res.insert(x);
        for (int x : s2) if (s3.count(x)) res.insert(x);
        return vector<int>(res.begin(), res.end());
    }
};

class Solution {
    public List<Integer> twoOutOfThree(int[] nums1, int[] nums2, int[] nums3) {
        Set<Integer> s1 = new HashSet<>();
        for (int x : nums1) s1.add(x);
        Set<Integer> s2 = new HashSet<>();
        for (int x : nums2) s2.add(x);
        Set<Integer> s3 = new HashSet<>();
        for (int x : nums3) s3.add(x);

        Set<Integer> res = new HashSet<>();
        for (int x : s1) if (s2.contains(x) || s3.contains(x)) res.add(x);
        for (int x : s2) if (s3.contains(x)) res.add(x);
        return new ArrayList<>(res);
    }
}

var twoOutOfThree = function(nums1, nums2, nums3) {
  const s1 = new Set(nums1);
  const s2 = new Set(nums2);
  const s3 = new Set(nums3);
  const res = new Set();
  for (const x of s1) if (s2.has(x) || s3.has(x)) res.add(x);
  for (const x of s2) if (s3.has(x)) res.add(x);
  return Array.from(res);
};
